import{K as l,a as r,c as i,b as e,k as n,q as s,ac as c}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"Outlook 搜索、文件夹、分类与规则","description":"用搜索过滤、标记、分类和文件夹处理邮件，建立可验证的收件规则，区分归档与删除，排查规则未生效和邮箱容量。","frontmatter":{"title":"Outlook 搜索、文件夹、分类与规则","description":"用搜索过滤、标记、分类和文件夹处理邮件，建立可验证的收件规则，区分归档与删除，排查规则未生效和邮箱容量。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Outlook 邮件与日程","summary":"用搜索过滤、标记、分类和文件夹处理邮件，建立可验证的收件规则，区分归档与删除，排查规则未生效和邮箱容量。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Outlook 邮件撰写、附件与往来管理","link":"/tools/office/outlook/mail"},"next":{"text":"Outlook 日历、会议邀请与时间管理","link":"/tools/office/outlook/calendar"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Outlook 邮件撰写、附件与往来管理","link":"/tools/office/outlook/mail"},"next":{"text":"Outlook 日历、会议邀请与时间管理","link":"/tools/office/outlook/calendar"}},"headers":[],"relativePath":"tools/office/outlook/organize.md","filePath":"tools/office/outlook/organize.md"}'),h={name:"tools/office/outlook/organize.md"},f=Object.assign(h,{setup(u){const a={path:"/tools/office/outlook/organize",app:"Outlook",title:"用一条小范围规则整理测试邮件",steps:[{tab:"文件夹列表右键菜单",command:"新建文件夹",setting:"文件夹：月报测试；位置：当前邮箱",anchor:"walkthrough-1",surface:"area"},{tab:"开始",command:"规则",setting:"主题包含：月报规则测试；移动到：月报测试",anchor:"walkthrough-2"},{tab:"文件",command:"管理规则和通知",setting:"检查规则顺序；测试后关闭规则",anchor:"walkthrough-3"}]};return(k,o)=>{const t=l("OfficeGuide");return r(),i("div",null,[o[0]||(o[0]=e("h1",{id:"outlook-搜索、文件夹、分类与规则",tabindex:"-1"},[n("Outlook 搜索、文件夹、分类与规则 "),e("a",{class:"header-anchor",href:"#outlook-搜索、文件夹、分类与规则","aria-label":'Permalink to "Outlook 搜索、文件夹、分类与规则"'},"​")],-1)),o[1]||(o[1]=e("p",null,"邮件整理的目的不是让收件箱数字归零，而是让待办不遗漏、已办可查。先建立少量明确规则，再考虑自动分类，避免重要邮件被自动移走后无人处理。",-1)),s(t,{guide:a}),o[2]||(o[2]=c('<h2 id="search" tabindex="-1">用搜索代替逐层翻找 <a class="header-anchor" href="#search" aria-label="Permalink to &quot;用搜索代替逐层翻找 {#search}&quot;">​</a></h2><p>在搜索框输入主题关键词，再使用界面的发件人、日期、附件等筛选条件缩小范围。先确认搜索的是当前文件夹、当前邮箱还是所有邮箱；搜索不到不等于邮件不存在。</p><p>如果只记得附件名，试按附件相关条件搜索；如果只记得某个时间段，先缩小日期再加关键词。会话视图可能把多封邮件折叠在一起，检查是否显示了完整会话和其他文件夹中的相关消息。经典版索引、在线连接或缓存范围也可能影响搜索结果。</p><h2 id="organize" tabindex="-1">文件夹、分类和标记 <a class="header-anchor" href="#organize" aria-label="Permalink to &quot;文件夹、分类和标记 {#organize}&quot;">​</a></h2><p>文件夹适合稳定归档位置，例如“项目 A”“通知”；分类适合跨文件夹的标签，例如“待确认”“财务”；标记适合提醒跟进。各版本对分类、提醒和任务集成的支持不同，先在自己的环境做一次测试。</p><p>可以从三类工作开始：需要自己行动的邮件标记跟进，需要别人答复的邮件标记等待，处理完成的邮件归档到对应项目。不要同时建立大量含义接近的标签，最后自己也无法判断应该放哪里。</p><p>归档通常把邮件移到归档文件夹，不等于删除，也不必然减少邮箱占用。在线存档、自动存档和本地数据文件是不同功能，企业保留策略也可能影响行为，操作前确认实际名称和说明。</p><h2 id="rules" tabindex="-1">建立一条可检查的规则 <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;建立一条可检查的规则 {#rules}&quot;">​</a></h2><p>以“把自己测试发送、主题包含 <code>[练习通知]</code> 的邮件移到练习文件夹”为例：</p><ol><li>先建立目标文件夹 <code>练习通知</code>。</li><li>新 Outlook 或网页版通常可在“设置 → 邮件 → 规则”管理；经典版可从“规则 → 管理规则和通知”进入。</li><li>明确发件人和主题条件，动作只设置移动到目标文件夹。</li><li>检查例外和规则顺序，避免先前的规则已经移动或删除该邮件。</li><li>使用自己的测试邮件验证，确认符合条件的一封被移动，不符合的一封保留原处。</li></ol><p>某些规则由服务器执行，某些经典版规则依赖客户端运行；不要认为关闭电脑后所有规则都照常工作。<a href="https://support.microsoft.com/en-us/outlook/training/organize-email-with-outlook-on-the-web" target="_blank" rel="noopener noreferrer">微软网页版规则示例</a></p><h2 id="troubleshoot" tabindex="-1">排查规则和容量问题 <a class="header-anchor" href="#troubleshoot" aria-label="Permalink to &quot;排查规则和容量问题 {#troubleshoot}&quot;">​</a></h2><p>规则没生效时检查是否启用、是否针对正确账号、条件是否精确匹配、目标文件夹是否仍存在，以及更靠前规则是否设置停止处理后续规则。旧邮件是否需要手工运行规则，应查看实际版本提供的选项。</p><p>邮箱空间不足时先使用按大小和附件筛选定位大邮件，再按组织保留要求处理。删除邮件可能先进入已删除文件夹，清空前确认需要保留的业务记录；不要把个人电脑上的 PST 当作团队唯一长期档案。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>建立一条只针对测试主题的规则，测试后关闭该规则，观察新邮件恢复正常位置。再用发件人、日期和主题三项条件找到测试邮件。你应能解释每封邮件为何在当前文件夹，以及它是否仍需要后续行动。</p><h2 id="walkthrough" tabindex="-1">图示跟做：用一条小范围规则整理测试邮件 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：用一条小范围规则整理测试邮件 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先确定邮件将被移动到哪里 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先确定邮件将被移动到哪里 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：文件夹列表右键菜单 → 新建文件夹。</strong></p><p>在当前邮箱的文件夹列表右击，选择新建文件夹，命名月报测试。准备一封主题含独特测试词的现有邮件，记录原位置；不要用过宽的“包含报告”来练习，否则可能移动大量无关历史邮件。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：在经典 Outlook 创建规则 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：在经典 Outlook 创建规则 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：开始 → 规则。</strong></p><p>经典 Outlook 可右击测试邮件，选择“规则 → 创建规则”，限定主题条件和目标文件夹，检查是否还包含其他自动勾选的条件。新版 Outlook 从设置里的邮件规则进入，界面和支持范围不同。首次不要自动对整个邮箱历史邮件运行。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：验证命中与不命中两种情况 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：验证命中与不命中两种情况 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：文件 → 管理规则和通知。</strong></p><p>在经典 Outlook 管理规则和通知中检查条件、目标文件夹和执行顺序。用已获授权的测试邮件验证匹配主题会移动、普通主题仍保持原位置，必要时只对测试文件夹中的现有邮件运行。练习结束关闭该规则，再通过搜索找回测试邮件。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>规则不运行时区分服务器规则与需要经典客户端运行的规则，并检查其他规则是否提前处理或停止后续规则。规则移动邮件不会表示该邮件已经办结，待办状态需要另行管理。</p><p>图示操作参考：<a href="https://support.microsoft.com/zh-cn/outlook/mail/manage-email-messages-by-using-rules-in-outlook" target="_blank" rel="noopener noreferrer">微软官方：新版与经典 Outlook 规则入口</a>。核对日期：2026-11-02；界面示意与练习案例为本站独立编写。</p>',30))])}}});export{p as __pageData,f as default};
